class PromotionService {
    // Không sửa tham số: trả về danh sách mới
    List<OrderLine> withFreeGift(List<OrderLine> lines) {
        int total = lines.stream().mapToInt(OrderLine::qty).sum();
        if (total < 3) {
            return List.copyOf(lines);        // không tốn gì nếu đã bất biến
        }
        var result = new ArrayList<>(lines);
        result.add(new OrderLine("GIFT-BAG", 1));
        return List.copyOf(result);
    }
}

List<OrderLine> lines = promotionService.withFreeGift(cartBuilder.lines(cart.items()));

// Test dựng input bằng List.of để bắt cả trường hợp list không sửa được
@Test
void addsGiftFromThreeItems() {
    var lines = List.of(new OrderLine("TSHIRT", 2), new OrderLine("CAP", 1));
    assertThat(promotionService.withFreeGift(lines)).hasSize(3);
}
